  function drawSkid3d(s) {
    const fx = Math.cos(s.angle);
    const fy = Math.sin(s.angle);
    const rx = -fy;
    const ry = fx;
    const a = Math.min(0.55, (s.life / 2.5) * 0.55);
    poly3([
      { x: s.x - fx * 16 - rx * 3, y: s.y - fy * 16 - ry * 3, z: 0.2 },
      { x: s.x + fx * 16 - rx * 3, y: s.y + fy * 16 - ry * 3, z: 0.2 },
      { x: s.x + fx * 16 + rx * 3, y: s.y + fy * 16 + ry * 3, z: 0.2 },
      { x: s.x - fx * 16 + rx * 3, y: s.y - fy * 16 + ry * 3, z: 0.2 },
