  function drawBullet3d(b) {
    const a = projectPoint(cam, b.x - Math.cos(b.angle) * 18, b.y - Math.sin(b.angle) * 18, 6);
    const c = projectPoint(cam, b.x, b.y, 6);
    if (!a || !c) return;
    ctx.strokeStyle = '#ffee58';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(c.x, c.y);
    ctx.stroke();
